for(const [source,en,nl] of [...creationWorkflowMessages,...studioErrors]){
 translations[`Impossible d’ouvrir ce visuel. ${source}`]={en:`Unable to open this graphic. ${en}`,nl:`Dit beeld kan niet worden geopend. ${nl}`};
 translations[`L’export n’a pas abouti. ${source}`]={en:`Export did not finish. ${en}`,nl:`Het exporteren is niet gelukt. ${nl}`};
 translations[`La création n’a pas pu être lancée. ${source}`]={en:`The creation could not start. ${en}`,nl:`De creatie kon niet worden gestart. ${nl}`};
}
patterns.push(
 {source:String.raw`^La création n’a pas pu être lancée\. ([\s\S]+)$`,en:'The creation could not start. $1',nl:'De creatie kon niet worden gestart. $1'},
 {source:String.raw`^1 exemple · (\d+) sélectionnés?$`,en:'1 example · $1 selected',nl:'1 voorbeeld · $1 geselecteerd'},
 {source:String.raw`^(\d+) exemples · (\d+) sélectionnés?$`,en:'$1 examples · $2 selected',nl:'$1 voorbeelden · $2 geselecteerd'},
 {source:String.raw`^Importation (\d+) / (\d+)$`,en:'Importing $1 / $2',nl:'Importeren $1 / $2'},
 {source:String.raw`^1 fichier ajouté à la bibliothèque\.$`,en:'1 file added to the library.',nl:'1 bestand aan de bibliotheek toegevoegd.'},
 {source:String.raw`^(\d+) fichiers ajoutés à la bibliothèque\.$`,en:'$1 files added to the library.',nl:'$1 bestanden aan de bibliotheek toegevoegd.'},
);

